const TABLES = { en, es, pt, hi, id };
let cur = en, curCode = 'en';
export function pickLang(code) {
  const base = String(code || '').toLowerCase().split(/[-_]/)[0];
  return TABLES[base] ? base : 'en';
}
export function setLang(code) { curCode = pickLang(code); cur = TABLES[curCode]; return curCode; }
export function getLang() { return curCode; }
export function t(key, vars) {
  let s = cur[key] ?? en[key] ?? key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m));
  return s;
}
// Missing-key check used by the test script
export function missingKeys() { const out = {}; for (const [c, tab] of Object.entries(TABLES)) { const miss = Object.keys(en).filter((k) => !(k in tab)); if (miss.length) out[c] = miss; } return out; }
